window.CONTENT_PARTS = window.CONTENT_PARTS || [];
window.CONTENT_PARTS.push({ lang: "en", units: [

{ id: "en-exam", group: "Start here", order: 15,
  title: "Exam day strategies",
  intro: "On exam day, a calm plan matters as much as good ideas. Learn how to use your time well, what to do if you get stuck, and how to turn your teacher’s comments into a better story.",
  blocks: [
    { type: "text", html: "Think of the exam like a football match. The best players do not just run around kicking the ball. They know the game plan, they watch the clock, and they keep calm when something goes wrong. In this lesson you will build your own exam game plan, so that on the day you can stop worrying and start writing." },
    { type: "steps", title: "Your game plan from start to finish", items: [
      { title: "Settle in and breathe", text: "Before you turn the page, take three slow breaths. Write your name and class neatly. A calm brain thinks of better ideas than a panicking one, so these few seconds are never wasted." },
      { title: "Read the question twice", text: "Read the title, the helping words and the instructions slowly, two times. Underline the key words, such as <i>a time you were brave</i> or <i>an unexpected visitor</i>. Ask yourself: what MUST happen in my story so that it fits the title?" },
      { title: "Choose your picture wisely", text: "If there are pictures, look at each one for a few seconds. Pick the picture that gives you the clearest problem and the strongest feelings, not just the prettiest one. Make sure the picture plays an important part in your story, not a tiny mention at the end." },
      { title: "Plan on your story mountain", text: "Spend about ten minutes jotting short notes for the beginning, build-up, climax, solution and ending. Decide your main character, the setting, the problem and the lesson. Circle the climax: that is where you will spend the most words." },
      { title: "Write with one eye on the clock", text: "Glance at the clock after every paragraph. Keep the opening short and get to the problem quickly. Slow down at the climax with feelings, senses and actions. Leave enough time to write a proper ending." },
      { title: "Check with your five-minute routine", text: "Stop writing with about five minutes left and check your work using the routine below. Even two or three corrections can make your story clearer and more accurate." }
    ] },
    { type: "tip", html: "<b>Clock tip:</b> Before you start writing, jot small times in the margin of your planning paper, for example <i>“Climax by 10.25”</i> and <i>“Stop and check at 10.45”</i>. Then you only need to glance at the clock to know if you are on track." },
    { type: "steps", title: "The five-minute checking routine", items: [
      { title: "Minute 1: Does it answer the question?", text: "Read your first and last paragraphs. Is the title clearly linked to your main event? If you used a picture, is it clearly in the story? If not, add one sentence in the ending that ties it back to the topic." },
      { title: "Minute 2: Are the tenses steady?", text: "Run your finger along each line looking at the verbs. Your story should stay in the past tense: <i>ran, saw, thought, was</i>. Watch out for slips like <i>“I run to the door”</i> in the middle of an exciting part." },
      { title: "Minute 3: Full stops, capitals and speech marks", text: "Check that every sentence starts with a capital letter and ends with a full stop, question mark or exclamation mark. Check that every piece of speech has opening and closing speech marks, and a comma or other punctuation before the closing mark." },
      { title: "Minute 4: Spelling and missing words", text: "Look for words you often get wrong, such as <i>their/there, quite/quiet, received, beautiful, embarrassed</i>. Read each sentence quietly in your head, as if you were saying it aloud. Your ear will catch words you left out, like <i>“I went the shop.”</i>" },
      { title: "Minute 5: One final polish", text: "Look at your paragraphs. Does each one start on a new line? Is there a strong verb or a feeling word you could swap in? Fix one or two small things neatly. Do not start rewriting whole paragraphs now." }
    ] },
    { type: "tip", html: "<b>Know your own mistakes:</b> Every writer has favourite mistakes. Maybe you forget closing speech marks, or you mix up <i>its</i> and <i>it’s</i>. Make a list of your top three from past compositions and hunt for those first when you check." },
    { type: "cards", title: "If you get stuck or run out of time", items: [
      { tag: "Stuck", title: "I cannot think of an idea", text: "Do not stare at the paper. Ask yourself four quick questions: Who? Where? What went wrong? How did it end? Then think of something that really happened to you or a friend, and change it a little. Real-life ideas are easier to write and feel more believable.", ex: "Topic: “A Lucky Escape”. You remember nearly tripping on the MRT platform gap. Turn it into a story where you are carrying Grandma’s birthday cake." },
      { tag: "Stuck", title: "I am stuck in the middle", text: "Look back at your plan. Which stage comes next? If you did not plan that part, ask: what is the worst thing that could happen now? Then show how your character reacts. A problem gets a story moving again.", ex: "The class is preparing for the concert... and then the piano teacher calls in sick." },
      { tag: "Stuck", title: "I cannot remember a good word", text: "Use a simple word you are sure of and keep going. A correct simple word is far better than a fancy word used wrongly. If the better word comes back to you during checking, you can neatly change it then." },
      { tag: "Time", title: "The climax is not written and time is short", text: "Skip the extra detail you planned for the build-up and jump straight to the most important moment. Write the climax with one or two strong feeling sentences, then a quick solution. A story with a climax and an ending is far better than one that stops halfway.", ex: "“Just then, a loud crash came from the kitchen.” This one line can move you straight to the action." },
      { tag: "Time", title: "I only have a few minutes left", text: "Write a short ending paragraph of two or three sentences: what happened in the end, how you felt and what you learnt. Never leave a story without an ending, even a very short one.", ex: "“As we walked home, I held Mei Ling’s hand a little tighter. I had learnt that a true friend tells you the truth, even when it is hard to hear.”" },
      { tag: "Mistake", title: "I wrote something wrong", text: "Draw one neat line through the mistake and write the correction above it or next to it. Do not scribble, colour over it or use lots of correction tape that makes the page messy. Your teacher only needs to see which version you want." },
      { tag: "Mistake", title: "I left out a sentence", text: "Put a small caret mark (^) where the sentence should go. Write the missing words neatly above the line, or write it at the bottom of the page with a star and the same star where it belongs." },
      { tag: "Worry", title: "My mind has gone blank", text: "Put your pencil down, take three slow breaths and read the question again. Look at the pictures and say what you see in your head. Blankness passes quickly when you stop fighting it." }
    ] },
    { type: "cards", title: "Keep it neat and easy to read", items: [
      { tag: "Paragraphs", title: "Show clearly where each paragraph starts", text: "Start each new paragraph on a new line. Leave a clear space at the start of the line, or follow the layout your teacher has taught you. Change paragraphs when there is a new time, a new place, a new speaker or a new event." },
      { tag: "Paragraphs", title: "Aim for five to seven paragraphs", text: "A short opening, two or three paragraphs building up to the climax, a rich climax paragraph, and a meaningful ending. One giant paragraph is very hard for a reader to follow." },
      { tag: "Handwriting", title: "Steady size and spacing", text: "Keep tall letters tall and small letters small. Leave a finger space between words. If your writing becomes faster and messier towards the end, slow down a little: a word nobody can read is a word nobody can mark." },
      { tag: "Handwriting", title: "Stay inside the lines", text: "Write on the line, not floating above it. Do not squeeze words into the margin at the end of a line. Start the word on the next line instead." },
      { tag: "Dialogue", title: "New speaker, new line", text: "Every time a different person speaks, start a new line. This keeps conversations clear and stops the reader from getting confused about who said what.", ex: "“Is anyone there?” I called.<br>“Over here!” came a weak voice." },
      { tag: "Corrections", title: "One neat line, no scribbles", text: "A single line through a mistake looks tidy. Heavy scribbles, smudges and arrows all over the page make a good story look careless." }
    ] },
    { type: "text", title: "What your teacher’s comments mean", html: "When your teacher writes a short comment on your composition, it is not a telling-off. It is a clue that shows you exactly what to work on next. Here are common comments, what they mean, and how to fix them." },
    { type: "cards", items: [
      { tag: "Comment", title: "“Lacks development”", text: "Your story moves too fast and important parts are only a sentence long. The reader does not get to feel what the character feels. <b>Fix it:</b> Find your climax and add actions, thoughts, feelings and the senses. Slow down time at the most exciting moment.", ex: "Before: “The boy fell into the drain. I helped him out.”<br>After: “With a loud splash, the boy slipped into the drain. I flung myself onto the wet grass, stretched out my arm and grabbed his wrist just as the water dragged him forward.”" },
      { tag: "Comment", title: "“Plot is predictable”", text: "Your teacher could guess the ending from the first paragraph, because it is a story many pupils write. <b>Fix it:</b> Keep the topic but change one thing: the character, the place or the problem. Add a small twist the reader does not expect.", ex: "Instead of “I found a wallet and returned it”, try: “I found a wallet, but it belonged to the boy who had been bullying me.”" },
      { tag: "Comment", title: "“Too much dialogue”", text: "Most of your story is people talking, and there is very little action, feeling or description. Long conversations slow the story down. <b>Fix it:</b> Keep only the lines that matter. Turn the rest into one sentence of action or reported speech.", ex: "Instead of six lines of “Hi!” “Hi!” “How are you?”, write: “After a quick hello, Priya pulled me aside and whispered the news.”" },
      { tag: "Comment", title: "“Rushed ending”", text: "You ran out of time or ideas, so the story ends in one or two quick lines with no feeling or lesson. <b>Fix it:</b> Plan your ending before you start writing, and watch the clock. Show what happened, how the character felt, and what they learnt or decided.", ex: "Before: “Then we went home. The end.”<br>After: “That night, I placed the cracked medal on my shelf. It was not gold, but it reminded me that I had never given up.”" },
      { tag: "Comment", title: "“Off-topic” or “Not relevant”", text: "Your story is about something else, or the topic only appears at the very end. <b>Fix it:</b> Underline the key words in the title and make them the heart of the climax. Ask: could someone guess the title from my main event?", ex: "Title: “A Time I Was Honest”. The climax must be the moment you choose to tell the truth, not a day out where honesty is mentioned in the last line." },
      { tag: "Comment", title: "“Weak vocabulary” or “Simple language”", text: "You use the same plain words again and again, such as <i>nice, good, went, said, very</i>. <b>Fix it:</b> Swap weak verbs for precise ones, and show feelings instead of naming them. Use a few strong words well rather than many fancy words wrongly.", ex: "“I went to the stage very nervously” becomes “I shuffled towards the stage, my knees knocking together.”" },
      { tag: "Comment", title: "“Tell less, show more”", text: "You name feelings but do not show them. <b>Fix it:</b> Describe the body, face, actions and thoughts of the character.", ex: "“I was angry” becomes “I clenched my fists so hard that my nails dug into my palms.”" },
      { tag: "Comment", title: "“Check your tenses”", text: "Your story jumps between past and present tense. <b>Fix it:</b> Use the past tense for the whole story, except inside speech marks. Check every verb during your five-minute routine.", ex: "“I open the door and saw a stranger” becomes “I opened the door and saw a stranger.”" },
      { tag: "Comment", title: "“Run-on sentences”", text: "Many ideas are joined together with <i>and then</i> or commas, so a sentence goes on and on. <b>Fix it:</b> Break it into shorter sentences, or join two ideas with a proper connector such as <i>because, although, when</i>.", ex: "“I ran and then I saw the dog and then it barked and I screamed” becomes “I ran around the corner. A dog barked fiercely at me. I screamed.”" },
      { tag: "Comment", title: "“Unrealistic” or “Not believable”", text: "Something in your story could not really happen, such as a child carrying an adult out of a fire or catching a thief alone. <b>Fix it:</b> Let your character be brave in a realistic way: calling for help, staying calm, remembering safety rules.", ex: "Instead of fighting the robber, Wei Ming noted down the car plate number and called the police." },
      { tag: "Comment", title: "“Introduction too long”", text: "You spent a whole page on waking up, breakfast and the journey before anything happened. <b>Fix it:</b> Start close to the action. Your opening should be one short, interesting paragraph.", ex: "Skip “I woke up at seven and brushed my teeth.” Start with “The moment I stepped into the hall, I knew something was wrong.”" },
      { tag: "Comment", title: "“Repetitive sentence starters”", text: "Too many sentences begin with <i>I</i> or <i>Then</i>. <b>Fix it:</b> Start some sentences with an -ing word, a time phrase, a sound or a feeling.", ex: "“I ran. I hid. I waited.” becomes “Racing round the corner, I ducked behind a pillar. Seconds crawled by.”" }
    ] },
    { type: "avoid", title: "Exam traps to avoid", items: [
      "“Suddenly I woke up. It was all a dream.”",
      "Spending the first half of the story on waking up, bathing and having breakfast.",
      "Forcing a memorised story onto a title it does not fit.",
      "Starting a brand-new story halfway through because you changed your mind.",
      "Leaving the story without an ending because time ran out.",
      "Using a long, fancy word you are not sure of, just to impress.",
      "A superhero rescue where a child defeats robbers alone.",
      "Ten characters with names, when three would be enough.",
      "Switching from past tense to present tense in the exciting part.",
      "Mentioning the picture in only one tiny sentence."
    ], note: "Each of these makes a story harder to follow or less believable. Your teacher wants a clear, real and well-told story that answers the question, not a tricky or flashy one." },
    { type: "tip", html: "<b>Before exam week:</b> Read your last three corrected compositions. Write down the teacher’s comments that appear more than once. Those comments are your personal checklist, and fixing them is the fastest way to improve." },
    { type: "mcq", title: "Smart exam choices", intro: "Choose what a calm, clever writer would do.", items: [
      { q: "You have just turned the page and read the title. What should you do next?", o: ["Start writing your opening straight away so you do not waste time", "Read it again slowly and underline the key words", "Look around to see what others are writing"], a: 1, e: "Reading twice and underlining key words makes sure your whole story answers the question. A fast start in the wrong direction wastes far more time." },
      { q: "There are three pictures. Which one should you choose?", o: ["The one that gives you the clearest problem and strongest feelings", "The first one, because it is always the easiest", "The one with the most people in it", "The one that matches a story you once read in a book"], a: 0, e: "A picture with a clear problem helps you build a strong climax, and feelings make the story come alive." },
      { q: "You are halfway through and have not reached the climax, but the clock shows time is running short. What is the best move?", o: ["Keep describing the build-up in detail", "Rub out everything and start a shorter story", "Move straight to the most important moment, then write a short ending"], a: 2, e: "A complete story with a climax and an ending is far better than a beautiful beginning with no end." },
      { q: "During checking, you find a misspelt word. How should you correct it?", o: ["Scribble over it heavily so nobody sees it", "Draw one neat line through it and write the correct word above", "Leave it, because it is too late to change anything"], a: 1, e: "One neat line is clear and tidy. Heavy scribbles make the page messy and hard to read." },
      { q: "Which plan is the most useful?", o: ["A full page of complete sentences describing every event", "No plan at all, so you have more time to write", "Short notes for each stage of the story mountain, with the climax circled"], a: 2, e: "Short notes are quick to write and easy to follow. Circling the climax reminds you where to spend the most words." },
      { q: "Your teacher once wrote “rushed ending”. What should you do in the exam?", o: ["Plan your ending before you start and watch the clock", "Write the ending first, before the story", "Make the ending one line long so you save time"], a: 0, e: "Planning the ending and keeping track of time means you will have enough minutes to finish properly." },
      { q: "You cannot remember the word “exhausted”. What is the smartest choice?", o: ["Leave a blank space and hope to remember later", "Write “very very very tired”", "Make up a word that sounds similar", "Show it instead: “My legs felt like lead as I dragged myself home.”"], a: 3, e: "Showing the feeling is often even better than the fancy word, and you cannot get it wrong." },
      { q: "The title is “A Kind Deed”. Which climax fits best?", o: ["You win a drawing competition", "You help an elderly neighbour who has fallen at the void deck", "You go to the zoo and see a kind-looking panda"], a: 1, e: "The kind deed must be the main event of the story. Helping the neighbour is a kind act and can be the exciting heart of the story." },
      { q: "What should you check FIRST in your five-minute routine?", o: ["Whether every word is spelt perfectly", "Whether your handwriting is pretty", "Whether the story clearly answers the question"], a: 2, e: "Answering the question matters most. If the story is off-topic, perfect spelling cannot save it." },
      { q: "Halfway through, you think of a much better story idea. What should you do?", o: ["Keep going with your planned story and use the new idea another time", "Cross everything out and start the new story", "Add the new idea as a second story at the end"], a: 0, e: "Starting again in the middle of the exam almost always leads to an unfinished story. Save your great idea for practice at home." }
    ] }
  ] },

{ id: "en-themes", group: "Word banks", order: 29,
  title: "Theme packs",
  intro: "Many composition titles are really about a value, such as kindness, honesty or courage. Each pack gives you plot ideas, a strong opening, a strong ending and the words you need for that theme.",
  blocks: [
    { type: "text", html: "When you see a title like <i>“A Time I Showed Courage”</i> or <i>“A Lesson Learnt”</i>, ask yourself: what is the big theme? Once you know the theme, open the matching pack below. Use the plot ideas as a starting point, then make them your own by changing the characters, the place or the twist." },
    { type: "tip", html: "<b>Tip:</b> A theme should be <i>shown</i> through what your character does and chooses, especially at the climax. The ending is where you can say the theme out loud in a thoughtful reflection." },

    { type: "cards", title: "Kindness", items: [
      { tag: "Plot idea", title: "The lost grandmother", text: "On the way home from school, you notice an elderly woman wandering around the void deck, looking confused. She cannot remember which block she lives in. You stay with her, ask the security guard for help, and find her worried son.", ex: "Twist: she turns out to be the grandmother of the classmate nobody talks to." },
      { tag: "Plot idea", title: "The spilt tray", text: "At a busy hawker centre, a boy with a cast on his arm drops his tray of noodles. People stare but nobody moves. You help him clean up and share your own meal, even though you were very hungry." },
      { tag: "Plot idea", title: "The new girl", text: "A new classmate who has just moved from another country eats alone during recess every day. You invite her to join your group, even though your friends grumble. Slowly she helps your group win the class project." },
      { tag: "Opening", title: "A strong opening line", ex: "The old woman’s plastic bag split open, and twenty oranges went bouncing across the void deck like runaway tennis balls." },
      { tag: "Ending", title: "A strong ending line", ex: "I had given away only half an hour of my afternoon, yet the smile on Madam Lim’s face made me feel richer than any prize I had ever won." }
    ] },
    { type: "chips", groups: [ { title: "Kindness words and phrases", words: ["compassionate", "considerate", "generous", "thoughtful", "lend a helping hand", "went out of my way", "a warm smile", "sympathy", "gratitude welled up", "put myself in her shoes", "touched by the gesture", "a heart of gold"],
      ex: "Putting myself in her shoes, I knew how lonely she must have felt.", note: "Show kindness through actions first, then name it in the ending." } ] },

    { type: "cards", title: "Honesty", items: [
      { tag: "Plot idea", title: "The extra change", text: "The drinks stall auntie gives you ten dollars too much change. Your friend says, “Keep it, she won’t notice.” You walk away, then turn back, thinking of how hard she works in the heat all day." },
      { tag: "Plot idea", title: "The broken vase", text: "While playing ball indoors, you knock over Grandma’s precious vase from China. Your little brother is blamed. You must decide whether to stay silent or confess." },
      { tag: "Plot idea", title: "The answer sheet", text: "Before a spelling test, a classmate finds the teacher’s word list left on the table and offers it to you. You refuse and later have to decide whether to tell the teacher.", ex: "Twist: you score lower than your classmate, but your teacher praises you in front of the class for your honesty." },
      { tag: "Opening", title: "A strong opening line", ex: "Ten dollars. The crisp red note sat in my palm, and it was not mine." },
      { tag: "Ending", title: "A strong ending line", ex: "The truth had cost me my pocket money for a month, but it had given me something money could never buy: Mum’s trust." }
    ] },
    { type: "chips", groups: [ { title: "Honesty words and phrases", words: ["confess", "own up", "come clean", "guilty conscience", "a lump in my throat", "the truth gnawed at me", "tempted", "integrity", "trustworthy", "do the right thing", "a weight lifted off my shoulders", "honesty is the best policy"],
      ex: "The moment I owned up, a weight lifted off my shoulders.", note: "Show the struggle before the honest choice: guilt, temptation, fear." } ] },

    { type: "cards", title: "Courage", items: [
      { tag: "Plot idea", title: "The stage fright", text: "You are chosen to give a speech at the school assembly about recycling. On the day, your hands shake and your mind goes blank. You remember your grandfather’s advice and begin to speak." },
      { tag: "Plot idea", title: "Standing up for a friend", text: "Older boys at the playground keep snatching your friend’s water bottle and laughing. Everyone watches. You walk over, your heart thumping, and firmly tell them to stop, then report it to a teacher." },
      { tag: "Plot idea", title: "The swimming test", text: "You are terrified of deep water after a frightening fall into a pool when you were small. At the swimming lesson, you must jump into the deep end. Step by step, you face your fear.", ex: "Twist: your fear makes you the first to notice a younger child struggling in the water." },
      { tag: "Opening", title: "A strong opening line", ex: "Two hundred faces stared up at me from the school hall, and every word of my speech flew out of my head like a startled bird." },
      { tag: "Ending", title: "A strong ending line", ex: "My knees had trembled the whole time, and that is how I learnt that courage is not the absence of fear. It is taking the next step anyway." }
    ] },
    { type: "chips", groups: [ { title: "Courage words and phrases", words: ["summoned my courage", "took a deep breath", "gritted my teeth", "stood my ground", "my heart hammered", "faced my fear", "bold", "determined", "steeled myself", "mustered every ounce of courage", "rose to the challenge", "plucked up the courage"],
      ex: "Gritting my teeth, I stood my ground as the older boys towered over me.", note: "Brave characters still feel afraid. Show the fear, then the brave action." } ] },

    { type: "cards", title: "Responsibility", items: [
      { tag: "Plot idea", title: "The class pet", text: "You volunteer to look after the class hamster during the holidays. You get busy with games and forget to refill its water. On the third day you find it weak and limp, and you rush to fix your mistake." },
      { tag: "Plot idea", title: "Looking after a sibling", text: "Mum asks you to watch your little brother at the playground while she buys groceries at the market. You get distracted by your phone, and when you look up, he is gone." },
      { tag: "Plot idea", title: "The group leader", text: "You are made leader of your science project group. Two members do no work, and the deadline is tomorrow. Instead of blaming them, you find a way to get everyone involved.", ex: "Twist: one member is quiet because she is struggling at home, and you learn to listen before you judge." },
      { tag: "Opening", title: "A strong opening line", ex: "One glance at the empty swing was enough. My little brother had vanished, and it was all my fault." },
      { tag: "Ending", title: "A strong ending line", ex: "Now, whenever someone trusts me with a job, I remember that empty water bottle in Nibbles’ cage, and I do not let them down." }
    ] },
    { type: "chips", groups: [ { title: "Responsibility words and phrases", words: ["reliable", "dependable", "duty", "entrusted", "take charge", "keep my word", "careless", "negligent", "a pang of guilt", "learnt my lesson", "owned my mistake", "never again"],
      ex: "Mr Tan had entrusted me with the keys, and I had been careless.", note: "Responsibility stories often begin with a mistake. Show how the character fixes it." } ] },

    { type: "cards", title: "Perseverance", items: [
      { tag: "Plot idea", title: "The cross-country run", text: "You come last in the class running test. Instead of giving up, you train every evening around your estate park with your dad. Months later, you run in the inter-class race." },
      { tag: "Plot idea", title: "The tricky piece", text: "You are learning a difficult piece on the piano (or guzheng, or violin) for a performance. You make the same mistake again and again and want to quit. You break it into small bits and practise patiently." },
      { tag: "Plot idea", title: "The science fair model", text: "Your model volcano collapses twice the night before the science fair. Tired and frustrated, you try a new design with your grandfather’s help.", ex: "Twist: you do not win, but the judge asks to use your model to teach younger pupils." },
      { tag: "Opening", title: "A strong opening line", ex: "For the fifth time that evening, the same wrong note clanged out of the piano, and I slammed the lid shut." },
      { tag: "Ending", title: "A strong ending line", ex: "I did not cross the finish line first, but I crossed it running, and to me that was the greatest victory of all." }
    ] },
    { type: "chips", groups: [ { title: "Perseverance words and phrases", words: ["persevere", "persistent", "determined", "refused to give up", "tried again and again", "practice makes perfect", "setback", "frustration", "pushed through the pain", "never say die", "slowly but surely", "where there is a will, there is a way"],
      ex: "Despite every setback, I refused to give up.", note: "Show several failed attempts before the success. That makes the victory feel earned." } ] },

    { type: "cards", title: "Friendship", items: [
      { tag: "Plot idea", title: "The quarrel", text: "You and your best friend quarrel over a misunderstanding about a birthday party invitation. For a week you do not talk. A school camp forces you to share a tent, and the truth comes out." },
      { tag: "Plot idea", title: "Moving away", text: "Your best friend tells you her family is moving to another country. You spend the last week making a scrapbook of memories, and on the last day at the airport you give it to her." },
      { tag: "Plot idea", title: "The true friend", text: "You join a popular group and start ignoring your old friend. When you fall ill during a school trip, it is your old friend, not the new group, who stays by your side.", ex: "Twist: you find out your old friend had defended you when the popular group was laughing at you." },
      { tag: "Opening", title: "A strong opening line", ex: "For seven long days, Aisha and I had walked past each other at recess as if we were complete strangers." },
      { tag: "Ending", title: "A strong ending line", ex: "We still argue sometimes, about books and about who gets the window seat, but I know now that a true friend is someone who stays, even after the storm." }
    ] },
    { type: "chips", groups: [ { title: "Friendship words and phrases", words: ["inseparable", "loyal", "the best of friends", "a shoulder to cry on", "drifted apart", "patched things up", "misunderstanding", "forgive and forget", "a friend in need is a friend indeed", "stood by me", "shared secrets", "two peas in a pod"],
      ex: "After the misunderstanding, it took a rainy afternoon and a shared umbrella for us to patch things up.", note: "Friendship stories are strongest when the friendship is tested." } ] },

    { type: "cards", title: "Family", items: [
      { tag: "Plot idea", title: "Dad’s taxi", text: "You feel embarrassed that your dad drives a taxi when your classmates’ parents have office jobs. One rainy night, you ride along with him and see how hard he works and how kind he is to his passengers." },
      { tag: "Plot idea", title: "Grandpa in hospital", text: "Your grandfather falls ill and stays in hospital. The family takes turns to visit. You realise how much his stories and his cooking mean to you, and you make him a special gift." },
      { tag: "Plot idea", title: "The surprise for Mum", text: "You and your siblings plan a surprise for Mum’s birthday: cooking her favourite dish. Everything goes wrong in the kitchen, but the evening becomes the family’s favourite memory.", ex: "Twist: Mum reveals she had done the same thing for her own mother when she was your age." },
      { tag: "Opening", title: "A strong opening line", ex: "Smoke curled out of the frying pan, the rice cooker was beeping angrily, and Mum would be home in exactly twenty minutes." },
      { tag: "Ending", title: "A strong ending line", ex: "That night, as Dad’s taxi rolled away into the rain, I finally understood that every long day he worked was a quiet way of saying he loved us." }
    ] },
    { type: "chips", groups: [ { title: "Family words and phrases", words: ["close-knit", "bond", "sacrifice", "took for granted", "unconditional love", "family reunion", "precious memories", "grateful", "blood is thicker than water", "a lump formed in my throat", "cherish", "home sweet home"],
      ex: "I had taken Ah Ma’s cooking for granted until the kitchen fell silent.", note: "Small, everyday details make family stories touching: a smell, a habit, a favourite saying." } ] },

    { type: "cards", title: "Making a mistake", items: [
      { tag: "Plot idea", title: "The forbidden shortcut", text: "You take a shortcut through a construction site to get home faster, even though there is a warning sign. You slip and hurt your ankle, and you have to call your parents for help." },
      { tag: "Plot idea", title: "The careless click", text: "You download a game on Mum’s phone without asking and accidentally spend money on it. You must tell her before she sees the bill." },
      { tag: "Plot idea", title: "The cruel joke", text: "You make fun of a classmate’s accent to get a laugh, and the whole class joins in. Later you see him crying at the staircase and realise how hurtful your words were.", ex: "Twist: you discover he speaks three languages, and you ask him to teach you." },
      { tag: "Opening", title: "A strong opening line", ex: "The yellow sign said DANGER in big black letters, but I was late, I was hungry, and the shortcut was right there." },
      { tag: "Ending", title: "A strong ending line", ex: "My ankle healed in a few weeks, but the lesson stayed with me much longer: rules are not there to annoy us, they are there to protect us." }
    ] },
    { type: "chips", groups: [ { title: "Mistake words and phrases", words: ["regret", "remorse", "foolish", "reckless", "learnt my lesson", "if only I had listened", "a costly mistake", "my heart sank", "apologised sincerely", "make amends", "once bitten, twice shy", "turn over a new leaf"],
      ex: "Filled with remorse, I apologised sincerely and promised to make amends.", note: "The best mistake stories show the character changing afterwards." } ] },

    { type: "cards", title: "Gratitude", items: [
      { tag: "Plot idea", title: "The school cleaner", text: "You never noticed the cleaner who sweeps the canteen every day. When you lose your house keys, she is the one who finds them and waits after school to return them. You and your class plan a thank-you surprise for her." },
      { tag: "Plot idea", title: "A day without", text: "During a blackout in your HDB block, you spend a whole evening without lights, a fan or the internet. Sitting by candlelight with your family, you realise how much you usually take for granted." },
      { tag: "Plot idea", title: "The patient tutor", text: "Your older cousin spends every Saturday helping you with maths, even though she has her own exams. When you finally do well, you find a special way to thank her.", ex: "Twist: you find her old notebook and realise she failed maths once too." },
      { tag: "Opening", title: "A strong opening line", ex: "For three years, I had walked past Auntie Rosnah and her broom every single morning, and I had never once said good morning." },
      { tag: "Ending", title: "A strong ending line", ex: "A thank-you card is only a folded piece of paper, but when Auntie Rosnah held mine to her heart, I knew it carried more than words." }
    ] },
    { type: "chips", groups: [ { title: "Gratitude words and phrases", words: ["grateful", "thankful", "appreciate", "took it for granted", "count my blessings", "heartfelt thanks", "indebted", "a token of appreciation", "unsung heroes", "touched", "overwhelmed with gratitude", "never forget"],
      ex: "I had never realised that the cleaners were the unsung heroes of our school.", note: "Gratitude stories work well when the character first does not notice, then suddenly sees." } ] },

    { type: "cards", title: "Teamwork", items: [
      { tag: "Plot idea", title: "The relay baton", text: "Your class relay team argues about who should run the last leg. During the race, a teammate drops the baton. Instead of blaming her, the team encourages her and still finishes strongly." },
      { tag: "Plot idea", title: "The class mural", text: "Your class must paint a mural for the school’s anniversary. Everyone wants their own idea. After a messy start, you suggest combining one idea from each person." },
      { tag: "Plot idea", title: "The flooded canteen", text: "A heavy storm floods part of the school canteen just before an open house. Pupils, teachers and the canteen vendors work together to clear it in time.", ex: "Twist: the quietest boy in class organises everyone with a clever plan." },
      { tag: "Opening", title: "A strong opening line", ex: "The baton slipped from Mei Ling’s fingers, clattered onto the track and rolled away, and our whole class gasped as one." },
      { tag: "Ending", title: "A strong ending line", ex: "Our mural is not perfect, but every time I walk past it, I can spot a little piece of each of my classmates, and that is exactly what makes it beautiful." }
    ] },
    { type: "chips", groups: [ { title: "Teamwork words and phrases", words: ["cooperate", "collaborate", "united", "pulled together", "worked hand in hand", "share ideas", "divide the tasks", "team spirit", "many hands make light work", "in this together", "compromise", "together we can"],
      ex: "Working hand in hand, we cleared the flooded canteen in under an hour.", note: "Show the team failing at first, then succeeding together." } ] },

    { type: "rewrite", title: "Write an opening for this theme", intro: "Read the theme and the situation. Write one or two opening sentences that hook the reader, then compare with the model.", items: [
      { q: "Theme: <b>Kindness</b>. Situation: an elderly man drops his walking stick on a crowded MRT train.", a: "The walking stick clattered onto the train floor, and the old man swayed like a tree in a storm as the carriage jolted forward.", hint: "Start with a sound or an action." },
      { q: "Theme: <b>Honesty</b>. Situation: you find a wallet full of money at a playground.", a: "It was lying under the slide, fat and brown and bulging with fifty-dollar notes, and nobody else had seen it.", hint: "Show the temptation." },
      { q: "Theme: <b>Courage</b>. Situation: you must sing a solo at the school concert.", a: "“Next up, Priya Nair!” The words echoed around the hall, and my legs refused to move.", hint: "Try speech." },
      { q: "Theme: <b>Responsibility</b>. Situation: you forgot to lock the gate and the family dog ran away.", a: "The gate was swinging gently in the wind, and Lucky’s lead lay on the floor beside it, empty.", hint: "Let the reader notice the problem through a detail." },
      { q: "Theme: <b>Perseverance</b>. Situation: you keep falling off your bicycle while learning to ride.", a: "Crash! For the ninth time that morning, I landed on the rough tarmac of the park connector, and for the ninth time, I picked myself up.", hint: "Show that it has happened many times." },
      { q: "Theme: <b>Friendship</b>. Situation: your best friend is not speaking to you after a misunderstanding.", a: "Jun Hao walked straight past my desk without a glance, and the empty chair beside him felt like a slammed door.", hint: "Use a simile or metaphor for the silence." },
      { q: "Theme: <b>Family</b>. Situation: your grandmother is moving in with your family.", a: "Ah Ma arrived with two suitcases, a rice cooker older than my father and a cage containing a very loud bird.", hint: "Use a funny or surprising detail." },
      { q: "Theme: <b>Making a mistake</b>. Situation: you lied to your parents about finishing your homework.", a: "“Yes, Mum, all done,” I said, and I felt the lie settle in my stomach like a cold, heavy stone.", hint: "Start with the lie itself." },
      { q: "Theme: <b>Gratitude</b>. Situation: you see the school bus driver working on his birthday.", a: "Uncle Ravi was humming as he wiped the bus windows at six in the morning, and nobody knew it was his birthday.", hint: "Introduce someone people usually ignore." },
      { q: "Theme: <b>Teamwork</b>. Situation: your team is losing badly at half-time in a football match.", a: "Three goals down, mud on our jerseys and twenty minutes left: our team huddled together in silence.", hint: "Try a short list to set the scene quickly." }
    ] }
  ] },

{ id: "en-patterns", group: "Building blocks", order: 23.5,
  title: "Sentence patterns",
  intro: "A sentence pattern is a ready-made shape you can pour your own ideas into. Learn these thirty patterns and your writing will sound more varied, more grown-up and more exciting.",
  blocks: [
    { type: "text", html: "Good writers do not use only one kind of sentence. They have a toolbox of patterns. When you know a pattern well, you can use it for any story: a lost wallet, a race, a quarrel or a storm. Start with the Level 1 patterns. When they feel easy, climb to Level 2 and then Level 3." },
    { type: "tip", html: "<b>Level 1 (start here):</b> As soon as..., Although..., It was so... that..., too... to..., the rule of three, -ing opener, Before I could..., The moment..., While..., With a.... These are rows 1 to 10 in the table." },
    { type: "tip", html: "<b>Level 2 (getting stronger):</b> Not only... but also..., Neither... nor..., Just as..., Without a word..., the feeling-word opener, Despite..., The more... the more..., Instead of..., If only...!, How I wished...!, the extra-information clause, Not a... could be heard. These are rows 11 to 22." },
    { type: "tip", html: "<b>Level 3 (challenge):</b> Little did I know that..., Hardly had... when..., No sooner had... than..., Never had I..., Only when... did I..., Not until... did I..., So + adjective + was... that..., Having + done.... These are rows 23 to 30. Notice that many of them flip the verb before the subject: <i>had I</i>, <i>did I</i>." },
    { type: "table", title: "Thirty sentence patterns", head: ["Pattern", "Example", "Use it to..."], rows: [
      ["1. As soon as ..., ...", "As soon as the bell rang, we raced to the canteen.", "show one action happening straight after another"],
      ["2. Although ..., ...", "Although I was exhausted, I kept pedalling up the slope.", "show a contrast or a struggle inside the character"],
      ["3. It was so ... that ...", "It was so quiet that I could hear the clock ticking in the next room.", "show how strong something was by its result"],
      ["4. too ... to ...", "I was too stunned to speak.", "show a feeling that stops an action"],
      ["5. Rule of three", "The hall was hot, crowded and buzzing with excitement.", "give a quick, rhythmic picture with three details"],
      ["6. -ing opener", "Clutching the trophy, Priya ran towards her parents.", "show two actions happening at the same time"],
      ["7. Before I could ..., ...", "Before I could shout a warning, the ball smashed into the window.", "show that something happened very fast"],
      ["8. The moment ..., ...", "The moment I saw the result slip, my heart sank.", "show an instant reaction"],
      ["9. While ..., ...", "While Mum was paying the cashier, my little brother slipped away.", "show two things happening at once, often to set up a problem"],
      ["10. With a ..., ...", "With a trembling hand, I pressed the doorbell.", "describe how someone does an action"],
      ["11. Not only ... but also ...", "Not only did Wei Ming return the wallet, but he also refused the reward.", "add a second, even more impressive point"],
      ["12. Neither ... nor ...", "Neither Jun Hao nor I dared to move a muscle.", "show that two people or things both did not"],
      ["13. Just as ..., ...", "Just as I reached the gate, the heavens opened.", "show bad (or good) timing"],
      ["14. Without a word, ...", "Without a word, Dad handed me his umbrella and walked into the rain.", "show a powerful silent action"],
      ["15. Feeling-word opener: Adjective, ...", "Exhausted, I collapsed onto the sofa.", "start with how the character feels"],
      ["16. Despite ..., ...", "Despite the pouring rain, the crowd stayed to cheer.", "show something happening even though there was a difficulty"],
      ["17. The more ..., the more ...", "The more I practised, the more confident I became.", "show something growing step by step"],
      ["18. Instead of ...ing, ...", "Instead of scolding me, Grandpa gave me a hug.", "show a surprising choice"],
      ["19. If only ...!", "If only I had listened to Mum!", "show regret in a mistake story"],
      ["20. How I wished ...!", "How I wished I could turn back the clock!", "show a strong longing or regret"],
      ["21. ..., which ..., ...", "The kitten, which had been missing for three days, was curled up in the shoe cabinet.", "slip extra information into the middle of a sentence"],
      ["22. Not a ... could be heard/seen", "Not a sound could be heard in the examination hall.", "show complete silence or emptiness"],
      ["23. Little did I know that ...", "Little did I know that this ordinary Monday would change my life.", "hint that something big is coming (foreshadowing)"],
      ["24. Hardly had ... when ...", "Hardly had I sat down when the fire alarm went off.", "show something happening almost immediately"],
      ["25. No sooner had ... than ...", "No sooner had Mum left the kitchen than the pot boiled over.", "show one event following another instantly"],
      ["26. Never had I ...", "Never had I felt so alone.", "show that a feeling or sight was the strongest ever"],
      ["27. Only when ... did I ...", "Only when I saw her tears did I realise how much I had hurt her.", "show a late realisation"],
      ["28. Not until ... did I ...", "Not until I reached home did I notice my wallet was missing.", "show something noticed too late"],
      ["29. So + adjective + was ... that ...", "So fierce was the storm that the old tree crashed onto the road.", "make a description sound dramatic"],
      ["30. Having + past participle, ...", "Having finished my homework, I rushed down to the void deck.", "show one action fully done before the next"]
    ] },
    { type: "tip", html: "<b>Watch the verbs:</b> In <i>Hardly had... when</i>, <i>No sooner had... than</i>, <i>Never had I</i>, <i>Only when... did I</i> and <i>Not until... did I</i>, the helping verb comes BEFORE <i>I</i>. Say <i>“No sooner had I sat down”</i>, never <i>“No sooner I had sat down”</i>. And remember: it is <i>No sooner... than</i>, but <i>Hardly... when</i>." },
    { type: "tip", html: "<b>Do not overdo it:</b> Two or three patterns in a composition are wonderful. Ten in a row will sound like a list of tricks. Save the fanciest ones for the most important moments, such as the climax or the ending." },
    { type: "rewrite", title: "Rewrite using the pattern", intro: "Join or change the sentences using the pattern given. Then reveal the model answer.", items: [
      { q: "Use <b>As soon as</b>: The bell rang. We rushed out of the classroom.", a: "As soon as the bell rang, we rushed out of the classroom." },
      { q: "Use <b>Although</b>: I was tired. I finished the race.", a: "Although I was tired, I finished the race." },
      { q: "Use <b>It was so... that</b>: The noodles were very spicy. My eyes watered.", a: "The noodles were so spicy that my eyes watered.", hint: "You can begin with “The noodles were so...”" },
      { q: "Use <b>too... to</b>: I was very scared. I could not move.", a: "I was too scared to move." },
      { q: "Use an <b>-ing opener</b>: Mei Ling waved her arms. She shouted for help.", a: "Waving her arms, Mei Ling shouted for help." },
      { q: "Use <b>Before I could</b>: I wanted to catch the plate. It smashed on the floor.", a: "Before I could catch the plate, it smashed on the floor." },
      { q: "Use <b>Not only... but also</b>: Aisha helped the old man up. She carried his shopping home.", a: "Not only did Aisha help the old man up, but she also carried his shopping home.", hint: "Begin with “Not only did...”" },
      { q: "Use <b>Just as</b>: I reached the bus stop. The bus drove away.", a: "Just as I reached the bus stop, the bus drove away." },
      { q: "Use <b>Despite</b>: It was raining heavily. The match went on.", a: "Despite the heavy rain, the match went on." },
      { q: "Use <b>The more... the more</b>: I read a lot. My vocabulary grew.", a: "The more I read, the more my vocabulary grew." },
      { q: "Use <b>Instead of</b>: Dad did not shout at me. He listened quietly.", a: "Instead of shouting at me, Dad listened quietly." },
      { q: "Use <b>Little did I know</b>: I did not know. The box held a puppy.", a: "Little did I know that the box held a puppy." },
      { q: "Use <b>Hardly had... when</b>: I opened my umbrella. The wind snatched it away.", a: "Hardly had I opened my umbrella when the wind snatched it away." },
      { q: "Use <b>No sooner had... than</b>: We stepped into the cinema. The lights went out.", a: "No sooner had we stepped into the cinema than the lights went out." },
      { q: "Use <b>Only when... did I</b>: I saw the empty cage. Then I realised the hamster had escaped.", a: "Only when I saw the empty cage did I realise the hamster had escaped." }
    ] },
    { type: "mcq", title: "Which sentence uses the pattern correctly?", intro: "Look closely at word order and joining words.", items: [
      { q: "Pattern: <b>No sooner had... than</b>", o: ["No sooner I had arrived than it rained.", "No sooner had I arrived when it rained.", "No sooner had I arrived than it started to rain."], a: 2, e: "The helping verb <i>had</i> comes before <i>I</i>, and the pattern uses <i>than</i>, not <i>when</i>." },
      { q: "Pattern: <b>Hardly had... when</b>", o: ["Hardly had we sat down when the lights flickered.", "Hardly we had sat down when the lights flickered.", "Hardly had we sat down than the lights flickered."], a: 0, e: "<i>Hardly had we</i> is the right order, and <i>hardly</i> pairs with <i>when</i>." },
      { q: "Pattern: <b>Not only... but also</b>", o: ["Not only she sang, but also danced.", "Not only did she sing, but she also danced.", "Not only did she sang, but she also danced.", "Not only she did sing, but also she danced."], a: 1, e: "After <i>did</i>, use the base verb <i>sing</i>, not <i>sang</i>. The word order is <i>Not only did she sing</i>." },
      { q: "Pattern: <b>too... to</b>", o: ["I was too tired that I could not walk.", "I was too tired to walking.", "I was too tired to walk another step."], a: 2, e: "<i>too</i> goes with <i>to</i> + base verb. <i>too... that</i> is a common mistake: use <i>so... that</i> instead." },
      { q: "Pattern: <b>Although</b>", o: ["Although it was late, but we kept searching.", "Although it was late, we kept searching.", "Although late, but we kept searching."], a: 1, e: "Never use <i>although</i> and <i>but</i> together. One contrast word is enough." },
      { q: "Pattern: <b>-ing opener</b>", o: ["Running to the bus stop, my bag fell open.", "Running to the bus stop, I felt my bag fall open.", "Running to the bus stop, the rain began."], a: 1, e: "The person after the comma must be the one doing the -ing action. A bag or the rain cannot run." },
      { q: "Pattern: <b>The more... the more</b>", o: ["The more I practised, the more I improved.", "More I practised, more I improved.", "The more I practised, I improved more."], a: 0, e: "Both halves need <i>the more</i>." },
      { q: "Pattern: <b>Only when... did I</b>", o: ["Only when I got home I did realise my mistake.", "Only when I got home did I realised my mistake.", "Only when I got home I realised my mistake.", "Only when I got home did I realise my mistake."], a: 3, e: "After <i>Only when...</i>, flip to <i>did I</i> and use the base verb <i>realise</i>." },
      { q: "Pattern: <b>Despite</b>", o: ["Despite of the rain, we went out.", "Despite it rained, we went out.", "Despite the rain, we went out."], a: 2, e: "<i>Despite</i> is followed by a noun (<i>the rain</i>) or an -ing word, never by <i>of</i> or a full clause." },
      { q: "Pattern: <b>Having + past participle</b>", o: ["Having finished my lunch, I went back to class.", "Having finish my lunch, I went back to class.", "Having finished my lunch, the bell rang."], a: 0, e: "Use the past participle <i>finished</i>, and the person after the comma must be the one who finished." }
    ] }
  ] },

{ id: "en-bank", group: "Practice", order: 59,
  title: "Opening and ending bank",
  intro: "A treasure chest of openings and endings for ten favourite themes. Read them, notice the technique on each card, then borrow the idea (not the exact words) for your own stories.",
  blocks: [
    { type: "text", html: "Each theme below has four openings and four endings, each using a different technique. The small label on every card tells you the technique. Try reading an opening, then covering the endings and guessing how the story might finish." },
    { type: "tip", html: "<b>Make it yours:</b> Do not copy a line word for word into your exam. Instead, keep the technique and change the details: the name, the place, the object, the sound. That way your story stays original and still sounds polished." },

    { type: "cards", title: "Kindness", items: [
      { tag: "Sound", title: "Opening", ex: "Clink, clink, clink. Coins spilled from the old man’s trembling hands and rolled under the seats of the bus." },
      { tag: "Question", title: "Opening", ex: "Would you give up your seat at the front of the queue for a stranger? That afternoon at the hawker centre, I had to decide in a heartbeat." },
      { tag: "Setting", title: "Opening", ex: "The void deck was empty except for the hum of a ceiling fan and a small girl sitting on the bench, crying into her school bag." },
      { tag: "Surprise", title: "Opening", ex: "The kindest person I have ever met never said a single word to me." },
      { tag: "Lesson", title: "Ending", ex: "That day I discovered that kindness does not need to be big or loud. Sometimes it is simply noticing someone everyone else has walked past." },
      { tag: "Circle back", title: "Ending", ex: "The next time I heard coins clinking on a bus, I was already on my knees, helping to pick them up." },
      { tag: "Promise", title: "Ending", ex: "I made a quiet promise to myself: every day, I would do one kind thing that nobody asked me to do." },
      { tag: "Image", title: "Ending", ex: "As the bus pulled away, the old man pressed his wrinkled hand against the window and smiled, and I carried that smile with me all the way home." }
    ] },

    { type: "cards", title: "Honesty", items: [
      { tag: "Thought", title: "Opening", ex: "<i>Nobody saw. Nobody will ever know.</i> The words whispered round and round in my head as I stared at the broken vase." },
      { tag: "Speech", title: "Opening", ex: "“Who did this?” Mum’s voice was low and dangerously calm, and my little brother looked straight at me." },
      { tag: "Action", title: "Opening", ex: "I slid the answer sheet into my drawer, slammed it shut and sat on my hands to stop them shaking." },
      { tag: "Flashback", title: "Opening", ex: "Even now, whenever I pass the drinks stall near my block, I remember the ten-dollar note that almost changed who I was." },
      { tag: "Feeling", title: "Ending", ex: "My punishment lasted a week, but the warm, clean feeling of having told the truth has lasted much longer." },
      { tag: "Saying", title: "Ending", ex: "Grandpa always said that a lie has short legs and never gets far. That evening, I finally understood what he meant." },
      { tag: "Last line", title: "Ending", ex: "Mum ruffled my hair. “Thank you for telling me,” she said. Somehow, that felt better than any excuse I could have made up." },
      { tag: "Reflection question", title: "Ending", ex: "I sometimes wonder what kind of person I would have become if I had kept quiet that day. I am glad I will never have to find out." }
    ] },

    { type: "cards", title: "Courage", items: [
      { tag: "Feeling", title: "Opening", ex: "My heart was hammering so loudly that I was sure the whole hall could hear it." },
      { tag: "Weather", title: "Opening", ex: "Thunder grumbled over the swimming complex as I stood at the edge of the deep end, my toes curled over the cold tiles." },
      { tag: "Short sentence", title: "Opening", ex: "Ten metres. That was all that stood between me and the scariest moment of my life." },
      { tag: "Speech", title: "Opening", ex: "“Stop it,” I said. My voice came out as a squeak, but the older boys turned around anyway." },
      { tag: "Lesson", title: "Ending", ex: "I learnt that being brave does not mean you are not scared. It means you are scared, and you do the right thing anyway." },
      { tag: "Change", title: "Ending", ex: "The boy who once hid behind his mother at every birthday party now volunteers to read at assembly. That boy is me." },
      { tag: "Image", title: "Ending", ex: "Standing on the diving board a month later, I looked down at the shimmering blue water and, for the first time, I smiled." },
      { tag: "Circle back", title: "Ending", ex: "My heart was still hammering as I walked off the stage, but this time it was beating with pride." }
    ] },

    { type: "cards", title: "Responsibility", items: [
      { tag: "Action", title: "Opening", ex: "I tore open the classroom door, dropped my bag and sprinted to the corner where Nibbles’ cage stood, silent and still." },
      { tag: "Ticking clock", title: "Opening", ex: "Mum would be back from the market in fifteen minutes, and my little brother was nowhere to be seen." },
      { tag: "Question", title: "Opening", ex: "Have you ever been given a job so important that your hands shook just holding the keys?" },
      { tag: "Setting", title: "Opening", ex: "The playground was a whirl of screaming children, squeaking swings and parents chatting under the trees, and somewhere in all that noise was Ethan." },
      { tag: "Promise", title: "Ending", ex: "I wrote a note and stuck it on my bedroom door: <i>If you say you will do it, do it.</i> It is still there today." },
      { tag: "Lesson", title: "Ending", ex: "Being responsible is not about being perfect. It is about owning your mistakes and doing everything you can to put them right." },
      { tag: "Feeling", title: "Ending", ex: "When Mr Tan handed the keys back to me the following term, I felt a quiet glow of pride. He trusted me again, and I had earned it." },
      { tag: "Last line", title: "Ending", ex: "Ethan slipped his sticky hand into mine. “Don’t lose me again, okay, Jie Jie?” “I won’t,” I said, and I meant it." }
    ] },

    { type: "cards", title: "Perseverance", items: [
      { tag: "Sound", title: "Opening", ex: "Clang! The same wrong note jangled out of the piano for the fifth time, and I buried my face in my hands." },
      { tag: "Number", title: "Opening", ex: "Forty-two. That was how many times I fell off my bicycle before the June holidays ended." },
      { tag: "Flashback", title: "Opening", ex: "Last year, I had finished the cross-country run dead last, with the teachers already packing up the finishing line." },
      { tag: "Weather", title: "Opening", ex: "The evening sun blazed down on the running track, and sweat stung my eyes as I began my tenth lap." },
      { tag: "Lesson", title: "Ending", ex: "Every fall had taught me something new. Success, I realised, is often just one more try after you feel like giving up." },
      { tag: "Circle back", title: "Ending", ex: "Forty-two falls, two scraped knees and one very patient father later, I was finally flying down the park connector with the wind in my hair." },
      { tag: "Saying", title: "Ending", ex: "Dad was right after all: slow and steady really does win the race, as long as you keep running." },
      { tag: "Image", title: "Ending", ex: "The battered practice book still sits on my piano, its pages soft and curled from use, a reminder of every evening I chose not to give up." }
    ] },

    { type: "cards", title: "Friendship", items: [
      { tag: "Speech", title: "Opening", ex: "“I’m never talking to you again!” Aisha’s words stung more than any scraped knee." },
      { tag: "Setting", title: "Opening", ex: "Under the old rain tree beside the school field, Mei Ling and I had shared our lunch, our secrets and our silliest jokes for five whole years." },
      { tag: "Surprise", title: "Opening", ex: "The day my best friend and I stopped talking to each other started with a single birthday invitation." },
      { tag: "Thought", title: "Opening", ex: "<i>She will say sorry first,</i> I told myself. <i>She has to.</i> But a week passed, and neither of us did." },
      { tag: "Feeling", title: "Ending", ex: "As we sat under the rain tree again, sharing a packet of curry puffs, I felt as if a missing piece of me had clicked back into place." },
      { tag: "Lesson", title: "Ending", ex: "Our quarrel taught me that pride can build a wall in a single day, but it takes courage to knock it down." },
      { tag: "Last line", title: "Ending", ex: "At the departure gate, Mei Ling hugged the scrapbook to her chest. “Same time next year?” she asked. “Same time next year,” I promised." },
      { tag: "Saying", title: "Ending", ex: "A friend in need is a friend indeed, and Jun Hao proved it when I needed him most." }
    ] },

    { type: "cards", title: "Family", items: [
      { tag: "Smell", title: "Opening", ex: "The smell of Ah Ma’s chicken curry drifted down the corridor long before I reached our front door." },
      { tag: "Action", title: "Opening", ex: "I yanked the frying pan off the stove, flapped a tea towel at the smoke alarm and prayed that Mum would be late." },
      { tag: "Flashback", title: "Opening", ex: "I used to hide in the back seat whenever Dad’s taxi stopped outside the school gate." },
      { tag: "Question", title: "Opening", ex: "When was the last time you told your parents you loved them? For me, it took a rainy night in Dad’s taxi to say it." },
      { tag: "Feeling", title: "Ending", ex: "Squeezed around our tiny dining table, laughing at the burnt cake, I felt happier than I had ever felt at any fancy restaurant." },
      { tag: "Change", title: "Ending", ex: "Now, when Dad’s taxi pulls up at the school gate, I am the first to wave, and I wave proudly." },
      { tag: "Promise", title: "Ending", ex: "I promised Grandpa that I would learn every one of his recipes, so that his kitchen would never fall silent." },
      { tag: "Image", title: "Ending", ex: "The photo from that evening still hangs on our fridge: five smiling faces, one lopsided cake and a kitchen that looked like a storm had hit it." }
    ] },

    { type: "cards", title: "Making a mistake", items: [
      { tag: "Regret", title: "Opening", ex: "If only I had walked the long way home that afternoon, I would never have seen the inside of a hospital." },
      { tag: "Short sentence", title: "Opening", ex: "One click. That was all it took to turn an ordinary Saturday into a very expensive mistake." },
      { tag: "Sound", title: "Opening", ex: "Crack! My foot slipped on the wet planks, and pain shot up my ankle like a bolt of lightning." },
      { tag: "Speech", title: "Opening", ex: "“It’s just a joke,” I said, as the whole class burst into laughter. Only one person was not laughing." },
      { tag: "Lesson", title: "Ending", ex: "Everyone makes mistakes. What matters is whether you learn from them, and I have never taken a shortcut past a warning sign again." },
      { tag: "Apology", title: "Ending", ex: "The next morning, I walked up to Arjun’s desk and said sorry, properly and in front of everyone, because the joke had been in front of everyone too." },
      { tag: "Reflection question", title: "Ending", ex: "How could a few careless words hurt so much? I still do not fully know, but I will never again laugh at someone just to fit in." },
      { tag: "Change", title: "Ending", ex: "Mum still lets me use her phone, but now I always ask first, and she always smiles when I do." }
    ] },

    { type: "cards", title: "Gratitude", items: [
      { tag: "Setting", title: "Opening", ex: "At half past six every morning, the school canteen was silent except for the soft swish of Auntie Rosnah’s broom." },
      { tag: "Surprise", title: "Opening", ex: "The most important lesson I learnt in Primary Four was taught by someone who was not a teacher." },
      { tag: "Senses", title: "Opening", ex: "Darkness swallowed our flat. The fan sighed to a stop, the fridge fell silent, and the air grew thick and still." },
      { tag: "Thought", title: "Opening", ex: "<i>Why does she always help me?</i> I wondered, watching my cousin rub her tired eyes over my maths worksheet." },
      { tag: "Lesson", title: "Ending", ex: "That blackout taught me to count my blessings: the light, the cool breeze of a fan, and most of all, the people sitting around me in the dark." },
      { tag: "Last line", title: "Ending", ex: "Auntie Rosnah read the card twice, tucked it into her apron pocket and whispered, “Nobody has ever thanked me before.”" },
      { tag: "Promise", title: "Ending", ex: "From that day on, I promised to say thank you, not just to my teachers, but to every unsung hero who keeps our school running." },
      { tag: "Feeling", title: "Ending", ex: "My heart swelled with gratitude, and I realised that a simple thank-you can light up someone’s whole day." }
    ] },

    { type: "cards", title: "Teamwork", items: [
      { tag: "Action", title: "Opening", ex: "The baton slipped from Mei Ling’s fingers, bounced once on the track and rolled away towards the crowd." },
      { tag: "Speech", title: "Opening", ex: "“My idea is better!” “No, mine is!” Our class mural meeting had lasted five minutes, and already everyone was shouting." },
      { tag: "Weather", title: "Opening", ex: "Rain hammered on the canteen roof all night, and by morning, brown water was swirling around the legs of every table." },
      { tag: "Rule of three", title: "Opening", ex: "Four teammates, one baton and a single lap to go: everything we had trained for came down to the next forty seconds." },
      { tag: "Lesson", title: "Ending", ex: "We did not win the gold, but we learnt something more valuable: a team is only as strong as the way it treats a teammate who stumbles." },
      { tag: "Saying", title: "Ending", ex: "Many hands make light work, and that morning, more than fifty pairs of hands turned a flooded canteen into a sparkling one." },
      { tag: "Image", title: "Ending", ex: "In the corner of the mural, hidden among the bright flowers, are thirty-two tiny handprints, one for every member of our class." },
      { tag: "Feeling", title: "Ending", ex: "As the four of us hugged on the track, mud on our knees and grins on our faces, I knew that this was what being a team really felt like." }
    ] },

    { type: "tip", html: "<b>Try this:</b> Choose one theme. Write your own opening using a technique from a <i>different</i> theme, for example a <i>Smell</i> opening for Courage or a <i>Ticking clock</i> opening for Friendship. Mixing and matching is how you find your own voice." }
  ] }

] });
